import React, { useEffect } from "react";
import io from "socket.io-client";

const backEndUrl = "http://localhost:8000";
let socket;

const Chat = () => {
    useEffect(() => {
        socket = io(backEndUrl);

        return () => {
            socket.disconnect(); // Cleanup the socket connection on unmount
        };
    }, []);

    return <p>Chat</p>;
};

export default Chat;
